param([switch]$Archive)
$ErrorActionPreference='Stop'
$root=$PSScriptRoot
& (Join-Path $root 'Verify-Evidence.ps1') | Out-Null
$evidence=Join-Path $root 'reports\latest'
$manifest=Get-Content -LiteralPath (Join-Path $evidence 'manifest.json') -Raw | ConvertFrom-Json
$counts=@(Select-String -LiteralPath (Join-Path $evidence 'tests.log') -Pattern '^ALL (\d+) ' | ForEach-Object {[int]$_.Matches[0].Groups[1].Value})
$total=($counts | Measure-Object -Sum).Sum
$ratios=@(Import-Csv -LiteralPath (Join-Path $evidence 'contrast.csv'))
$minimum=($ratios | ForEach-Object {[double]::Parse($_.Ratio,[Globalization.CultureInfo]::InvariantCulture)} | Measure-Object -Minimum).Minimum
$html=[Text.StringBuilder]::new()
[void]$html.Append('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GitPort UI review</title><style>body{margin:0;background:#1e2227;color:#cdd3de;font:15px/1.6 system-ui,sans-serif}main{max-width:1460px;margin:auto;padding:28px}h1,h2{color:#f1f4f9}h1{margin-bottom:6px}p{color:#a4adbc}code{color:#98c379;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,460px),1fr));gap:22px}figure{margin:0;padding:16px;background:#282c34;border:1px solid #3e4653;border-radius:10px}figure.wide{grid-column:1/-1}img{display:block;max-width:100%;height:auto;margin:auto}figcaption{margin-bottom:12px;color:#f1f4f9;font-weight:600}.note{padding:14px 18px;background:#282c34;border-left:3px solid #61afef;margin:20px 0}</style><main>')
[void]$html.Append('<h1>GitPort '+[Net.WebUtility]::HtmlEncode($manifest.version)+' — current UI smoke review</h1><p>Captured build: '+[Net.WebUtility]::HtmlEncode($manifest.completed_at)+'</p><div class="note">'+$total+' core/design checks passed. '+$ratios.Count+' text/background pairs pass 4.5:1 (minimum '+$minimum+':1). These are actual compiled app components using real Git operations on a disposable fixture repository. Bookmark names and sample code are test data.</div><p>Local authenticated loopback askpass passed in this run. Live HTTPS/SSH remote authentication remains unverified. No company repository or real credential was used.</p><p>JAR SHA-256: <code>'+$manifest.jar_sha256+'</code></p><div class="grid">')
foreach($capture in $manifest.screenshots){
    $image=[Convert]::ToBase64String([IO.File]::ReadAllBytes($capture.path));$wide=if($capture.name -match '^0[1236]'){' wide'}else{''}
    [void]$html.Append('<figure class="'+$wide+'"><figcaption>'+[Net.WebUtility]::HtmlEncode($capture.name)+'</figcaption><img alt="'+[Net.WebUtility]::HtmlEncode($capture.name)+'" src="data:image/png;base64,'+$image+'"><p>Captured '+[Net.WebUtility]::HtmlEncode($capture.captured_at)+'</p></figure>')
}
[void]$html.Append('</div><div class="note"><h2>Editor font options</h2><p>Settings > Appearance: bundled JetBrains Mono, Fira Code and Source Code Pro; system default, Cascadia Code, Consolas and Monospaced. Preview 11-22 pt, then press OK to save per profile. Cancel leaves preferences unchanged. The fixture acceptance test checks preview, cancel, save and immediate application. Programming ligatures are not enabled.</p><p>Text rendering: system smoothing restored at all display scales. Appearance now offers System / Windows ClearType, Grayscale, and No smoothing (pixel sharp) with a local preview and whole-interface application after OK. Automatic Java DPI transforms are preserved. Windows settings were unchanged. Live visual verification was unavailable because computer-use approval rejected access to the Java window.</p><p>These are programmatically rendered Swing fixture components, not interactive desktop or live-repository screenshots. Fixture components were also painted directly at 125%, 150% and 200% scale. These are synthetic graphics-transform checks, not live Windows monitor tests. Interactive keyboard/focus traversal and monitor changes remain untested.</p><p>Source/assets SHA-256: <code>'+[Net.WebUtility]::HtmlEncode($manifest.source_sha256)+'</code></p><p>Runnable app: <code>dist/GitPort/GitPort.exe</code>. Keep the complete GitPort folder together.</p></div></main></html>')
[IO.File]::WriteAllText((Join-Path $evidence 'UI-review.html'),$html.ToString(),[Text.UTF8Encoding]::new($false))
$note=@(('# GitPort '+$manifest.version+' validation — latest design'),'',('Completed: '+$manifest.completed_at),'',('- '+$total+' core/design checks passed; see reports/latest/tests.log.'),('- '+$ratios.Count+' text/background pairs passed; minimum measured contrast '+$minimum+':1.'),('- '+$manifest.screenshots.Count+' fresh captures from the packaged JAR: workspace layouts, grouped explorer filter, profiles, settings tabs, fixture merge conflict and splash.'),'- Verify-Evidence.ps1 checks source, artwork, JAR, native launcher, ICO and capture hashes before reporting.','- Native executable has the toolbox icon and version 0.2.0 metadata.','- Review fixed a settings-tab reparenting crash, clipped explorer hint, dialog/scrollbar styling, stale diff previews and oversized startup on smaller screens.','','Scope: rendered Swing components with real Git operations on disposable generated data. No user desktop or company repository was captured. Local loopback askpass passed. Live HTTPS/SSH remote authentication, production-repository performance, clean-Windows recovery and interactive keyboard/focus traversal remain unverified.','','Work stayed in the vera staging project; utility-tools, real repositories, profiles, credentials and system security were untouched.')
Set-Content -LiteralPath (Join-Path $root 'VALIDATION.md') -Value $note -Encoding utf8
Add-Content -LiteralPath (Join-Path $root 'VALIDATION.md') -Encoding utf8 -Value @('','Editor fonts: Settings > Appearance now includes bundled JetBrains Mono, Fira Code and Source Code Pro, system default, Cascadia Code, Consolas and Monospaced; preview and 11-22 pt sizing; per-profile persistence and immediate application to diff/history/activity/conflict text. Font preview/cancel/save, profile reload/isolation and diff-color preservation were tested with disposable fixtures. Programming ligatures are not enabled.')
Copy-Item -LiteralPath (Join-Path $root 'README.md'),(Join-Path $root 'VALIDATION.md'),(Join-Path $root 'DESIGN.md') -Destination (Join-Path $root 'dist\GitPort') -Force
if($Archive){
    Add-Type -AssemblyName System.IO.Compression
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $files=@();foreach($folder in @('src','assets','tools')){$files+=@(Get-ChildItem -LiteralPath (Join-Path $root $folder) -Recurse -File)}
    $files+=@(Get-ChildItem -LiteralPath $root -File | Where-Object {$_.Extension -in @('.ps1','.md') -or $_.Name -in @('.gitignore','SOURCE-ONLY.txt')})
    $files+=@(Get-ChildItem -LiteralPath $evidence -File)
    $files+=@($manifest.screenshots | ForEach-Object {Get-Item -LiteralPath $_.path})
    $captureReadme=Join-Path (Split-Path $manifest.screenshots[0].path) 'README.txt';if(Test-Path -LiteralPath $captureReadme){$files+=Get-Item -LiteralPath $captureReadme}
    $stream=[IO.File]::Open((Join-Path $root 'GitPort-source.zip'),[IO.FileMode]::Create)
    $zip=[IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Create,$false)
    try{foreach($file in @($files | Sort-Object FullName -Unique)){$entry=$file.FullName.Substring($root.Length).TrimStart('\').Replace('\','/');[IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip,$file.FullName,$entry,[IO.Compression.CompressionLevel]::Optimal) | Out-Null}}finally{$zip.Dispose();$stream.Dispose()}
}
Write-Host "Updated report from verified build $($manifest.version): $evidence\UI-review.html"
